#include <bits/stdc++.h>
using namespace std;

string input(bool read_file) {
    if (read_file) {
        ifstream file("sample.txt");
        string buf((istreambuf_iterator<char>(file)), istreambuf_iterator<char>());
        return buf;
    } else {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        string buf((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
        while (!buf.empty() && (buf.back() == '\n' || buf.back() == '\r' || buf.back() == ' ' || buf.back() == '\t'))
            buf.pop_back();
        return buf;
    }
}

void solve(vector<string>::iterator &it, vector<string>::iterator &end) {
    string s1 = (it != end ? *it++ : "");
    string s2 = (it != end ? *it++ : "");

    vector<char> v1(s1.begin(), s1.end());
    vector<char> v2(s2.begin(), s2.end());

    int p1 = 0;
    for (char c : v1) {
        if (c == '+') p1++;
        else p1--;
    }

    int p2 = 0;
    int uc = 0;
    for (char c : v2) {
        if (c == '+') p2++;
        else if (c == '-') p2--;
        else uc++;
    }

    vector<int> v;
    for (int bit = 0; bit < (1 << uc); ++bit) {
        int p = p2;
        for (int i = 0; i < uc; ++i) {
            if ((bit >> i) & 1) p++;
            else p--;
        }
        v.push_back(p);
    }

    int cnt = 0;
    for (int x : v) {
        if (x == p1) cnt++;
    }

    cout << fixed << setprecision(10) << (double)cnt / (double)v.size() << '\n';
}

int main() {
    const bool READ_FROM_FILE = false;

    string s = input(READ_FROM_FILE);

    stringstream ss(s);
    vector<string> tokens;
    string token;
    while (ss >> token) tokens.push_back(token);

    auto it = tokens.begin();
    auto end = tokens.end();

    solve(it, end);
    return 0;
}

